function nav(dest){ return {trigger:{type:'ON_CLICK'},actions:[{type:'SIMPLE_NAVIGATE',destinationId:dest.id,navigationSource:'NODE',transition:{type:'SMART_ANIMATE',duration:0.3,easing:{type:'EASE_IN_AND_EASE_OUT'}},resetVideoPosition:false,resetScrollPosition:false,resetComponentState:false}]}; }
function navPush(dest){ const r=nav(dest); r.actions[0].transition={type:'SLIDE_FROM_RIGHT',duration:0.3,easing:{type:'EASE_IN_AND_EASE_OUT'}}; return r; }
function navBack(dest){ const r=nav(dest); r.actions[0].transition={type:'SLIDE_FROM_LEFT',duration:0.3,easing:{type:'EASE_IN_AND_EASE_OUT'}}; return r; }
function navUp(dest){ const r=nav(dest); r.actions[0].transition={type:'SLIDE_FROM_BOTTOM',duration:0.3,easing:{type:'EASE_IN_AND_EASE_OUT'}}; return r; }
function findDeep(root,pred){ const q=[root]; while(q.length){ const n=q.shift(); if(pred(n)) return n; if('children' in n) q.push(...n.children);} return null; }
const log=[];
function link(srcNode,dest,mode){ if(!srcNode){log.push('MISSING');return;} srcNode.reactions=[...(srcNode.reactions||[]), mode==='push'?navPush(dest):mode==='back'?navBack(dest):mode==='up'?navUp(dest):nav(dest)]; log.push(srcNode.name+'->'+dest.name); }

